    // C[j][m] = (DATA_TYPE) (j*(m+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[m][l] = (DATA_TYPE) ((m*(l+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    // Simple parallel + vectorized schedules for initialization.
    Target init_target = get_jit_target_from_environment();
    int vec = init_target.natural_vector_size(type_of<num_t>());
    if (vec < 1) vec = 1;

    // Parallelize over the "row" dimension and vectorize over the x-fastest dim.
    init_A.compute_root()
          .parallel(i)
          .vectorize(k, vec);
    init_B.compute_root()
          .parallel(j)
          .vectorize(k, vec);
    init_C.compute_root()
          .parallel(j)
          .vectorize(m, vec);
    init_D.compute_root()
          .parallel(m)
          .vectorize(l, vec);

