    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=k/col, y=i/row)
    //           B[nk][nj] -> B(nj, nk)
    //           C[nj][nm] -> C(nm, nj)
    //           D[nm][nl] -> D(nl, nm)
    //           G[ni][nl] -> G(nl, ni)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    //
    // We choose coordinates so that the shared reduction dimension
    // between the three multiplications is always the x-fastest
    // dimension. This improves locality and makes SIMD vectorization
    // across the reduction-friendly dimension in the final multiply.
    Var i("i");   // row index of A and G  (0..ni-1)
    Var k("k");   // shared inner dimension for E and F (0..nj-1)
    Var l("l");   // column index of D and G (0..nl-1)

    RDom rAB(0, nk, "rAB");  // reduction over k_A for E = A * B (A: [ni x nk], B: [nk x nj])
    RDom rCD(0, nm, "rCD");  // reduction over k_C for F = C * D (C: [nj x nm], D: [nm x nl])
    RDom rEF(0, nj, "rEF");  // reduction over k (0..nj-1) for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{t=0..nk-1} A[i][t] * B[t][j]
    //
    // We store E as E(k, i) so that its first (x) dimension is the
    // "column" index j in the C code. This will become the reduction
    // dimension in the final multiply and is stored contiguous in
    // memory.
    //
    // Mapping to C:
    //   E(k, i) == E_C[i][k]
    Func E("E");
    E(k, i) = cast<num_t>(0);
    E(k, i) += A_param(rAB, i) * B_param(k, rAB);
    // A_param(rAB, i) = A_C[i][rAB]
    // B_param(k, rAB) = B_C[rAB][k]

    // 2) F := C * D
    // C: F[nj][nl] = sum_{t=0..nm-1} C[j][t] * D[t][l]
    //
    // We store F as F(k, l), again with the shared dimension k as x.
    //
    // Mapping to C:
    //   F(k, l) == F_C[k][l]
    Func F("F");
    F(k, l) = cast<num_t>(0);
    F(k, l) += C_param(rCD, k) * D_param(l, rCD);
    // C_param(rCD, k) = C_C[k][rCD]
    // D_param(l, rCD) = D_C[rCD][l]

    // 3) G := E * F
    // C: G[ni][nl] = sum_{t=0..nj-1} E[i][t] * F[t][l]
    //
    // We store G as G_func(l, i) so that:
    //   G_func(l, i) == G_C[i][l]
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(rEF, l);

    // -----------------------
    // Scheduling
    // -----------------------
    //
    // Goal:
    //  - Good data locality for all three matmuls.
    //  - Vectorize across x-fastest dimensions.
    //  - Parallelize outer dimensions to exploit many cores.
    //
    // Layout recap:
    //   A_param(k_A, i)   : k_A contiguous
    //   B_param(k_B, t)   : k_B contiguous
    //   C_param(m, k_C)   : m contiguous
    //   D_param(l, m)     : l contiguous
    //
    //   E(k, i)           : k contiguous
    //   F(k, l)           : k contiguous
    //   G_func(l, i)      : l contiguous
    //
    // The final G multiply uses E(rEF, i) and F(rEF, l), both varying
    // rEF along their x dimension (k), giving us perfectly coalesced
    // access for both inputs.

    Target target = get_jit_target_from_environment();
    int vec = target.natural_vector_size(type_of<num_t>());
    if (vec < 1) vec = 1;

    // ---- Schedule for E = A * B ----
    //
    // Parallelize across rows 'i' and vectorize across columns 'k'.
    // In the update, we make 'k' innermost so B_param(k, rAB) is
    // accessed contiguously and can be efficiently vectorized.
    E.compute_root()
     .parallel(i)
     .vectorize(k, vec);

    E.update()
     .reorder(k, rAB, i)   // innermost: k, then rAB, outermost: i
     .parallel(i)
     .vectorize(k, vec);

    // ---- Schedule for F = C * D ----
    //
    // Parallelize across output columns 'l' and vectorize across 'k'.
    // Again, in the update we put 'k' innermost for good locality
    // for F(k, l) and for the C/D accesses along their x-dimension.
    F.compute_root()
     .parallel(l)
     .vectorize(k, vec);

    F.update()
     .reorder(k, rCD, l)   // innermost: k, then rCD, outermost: l
     .parallel(l)
     .vectorize(k, vec);

    // ---- Schedule for G = E * F ----
    //
    // G_func(l, i) = sum_k E(k, i) * F(k, l)
    //
    //  - Parallelize across rows 'i'.
    //  - Vectorize across columns 'l' (x-fastest dimension).
    //  - In the reduction update, keep 'l' innermost so the writes to
    //    G_func and loads from F(k, l) are contiguous and vectorizable.
    G_func.compute_root()
          .parallel(i)
          .vectorize(l, vec);

    G_func.update()
          .reorder(l, rEF, i)  // innermost: l, then reduction rEF, outermost: i
          .parallel(i)
          .vectorize(l, vec);

    // Compile the kernel to machine code for the chosen target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
