int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=j/col, y=i/row)
    //           B[nk][nj] -> B(nj, nk)
    //           C[nj][nm] -> C(nm, nj)
    //           D[nm][nl] -> D(nl, nm)
    //           G[ni][nl] -> G(nl, ni)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over k for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over k for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------
    // Optimized schedule
    // ------------------------------------------------------------------
    //
    // Goal:
    //  - keep x (the first dimension) as the fastest-varying index
    //    for good spatial locality (matches Buffer layout)
    //  - parallelize across large outer dimensions (rows)
    //  - vectorize across the x dimension
    //
    // We use the host Target to pick a reasonable native vector width
    // for num_t on this machine.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Some helper Vars for tiling/vectorization.
    Var jo("jo"), ji("ji");
    Var lo("lo"), li("li");

    // --------------------------
    // Schedule for E = A * B
    // Shape: E(j, i)  -> width = nj (x = j), height = ni (y = i)
    // --------------------------

    // Pure definition (initialization to zero).
    // Iterate with i as outer loop, j as inner loop.
    E.compute_root()
        .reorder(j, i)                 // j (x) innermost for contiguous writes
        .split(j, jo, ji, 64)          // tile j for better cache behavior
        .parallel(i)                   // parallelize over rows of E
        .vectorize(ji, vec_width);     // vectorize across contiguous j

    // Update (reduction over rAB).
    // We keep the same outer-loop structure and put rAB innermost
    // to reuse A/B values in registers for each (i, j) pair.
    E.update()
        .reorder(rAB, j, i)           // for i: for j: for k:
        .split(j, jo, ji, 64)
        .parallel(i)
        .vectorize(ji, vec_width);

    // --------------------------
    // Schedule for F = C * D
    // Shape: F(l, j)  -> width = nl (x = l), height = nj (y = j)
    // --------------------------
    F.compute_root()
        .reorder(l, j)                 // l (x) innermost
        .split(l, lo, li, 64)
        .parallel(j)                   // parallelize over rows of F
        .vectorize(li, vec_width);

    F.update()
        .reorder(rCD, l, j)           // for j: for l: for k:
        .split(l, lo, li, 64)
        .parallel(j)
        .vectorize(li, vec_width);

    // --------------------------
    // Schedule for G = E * F
    // Shape: G_func(l, i) -> width = nl (x = l), height = ni (y = i)
    // --------------------------
    //
    // G is the final result, so we put most parallelism here.
    // We parallelize over i (rows of G) and vectorize across l.
    G_func.compute_root()
        .reorder(l, i)
        .split(l, lo, li, 64)
        .parallel(i)
        .vectorize(li, vec_width);

    G_func.update()
        .reorder(rEF, l, i)           // for i: for l: for j:
        .split(l, lo, li, 64)
        .parallel(i)
        .vectorize(li, vec_width);

    // Compile the kernel to machine code.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
